.local $rounded = {1.9 :number maximumFractionDigits=0}
.local $roundedOffset = {$rounded :offset add=1}
.local $negative = {-1.9 :offset add=1}
.local $integral = {0.0 :offset add=1}
.match $negative $integral
-0.9 one {{negative {$negative}; integral {$integral}; rounded {$roundedOffset}}}
* * {{fallback {$negative}; integral {$integral}; rounded {$roundedOffset}}}
